r';localStorage.setItem('unifco_language',l);const q=document.getElementById('side-nav-search');if(q)q.placeholder=l==='ar'?'بحث في القائمة…':'Search menu…';document.querySelectorAll('.unifco-language-switcher button').forEach(b=>b.classList.toggle('active',b.dataset.lang===l))}function mountTopbar(u){const zone=u.parentElement;if(!zone)return;zone.classList.add('top-user-zone');const name=u.textContent.trim();const initials=name.split(/\s+/).filter(Boolean).slice(0,2).map(x=>x[0]).join('').toUpperCase()||'U';const chip=document.createElement('span');chip.className='top-user-chip';const meta=document.createElement('span');meta.className='top-user-meta';const status=document.createElement('small');status.innerHTML='<span class="top-system-dot"></span> System Online';u.parentNode.insertBefore(chip,u);chip.appendChild(Object.assign(document.createElement('span'),{className:'top-user-avatar',textContent:initials}));meta.appendChild(u);meta.appendChild(status);chip.appendChild(meta)}function m(){const u=document.querySelector('.user-name');if(!u||document.querySelector('.unifco-language-switcher'))return;mountTopbar(u);const x=document.createElement('span');x.className='unifco-language-switcher';x.innerHTML='<button type="button" data-lang="ar">العربية</button><button type="button" data-lang="en">English</button>';const chip=document.querySelector('.top-user-chip')||u;x.addEventListener('click',e=>{const b=e.target.closest('button[data-lang]');if(b)set(b.dataset.lang)});chip.insertAdjacentElement('beforebegin',x);document.documentElement.dataset.unifcoLang='en';x.querySelector('[data-lang="en"]').classList.add('active');if((localStorage.getItem('unifco_language')||'en')==='ar')set('ar')}document.readyState==='loading'?document.addEventListener('DOMContentLoaded',m):m()})();
</script>
